tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlagts, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 22', function test( t ) {
	t.strictEqual( dlagts.length, 22, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not `1`, `-1`, `2`, or `-2`', function test( t ) {
	var values;
	var i;

	values = [
		0,
		3,
		-3,
		4,
		-4,
		1.5
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlagts( value, 3, new Float64Array( 3 ), 1, 0, new Float64Array( 2 ), 1, 0, new Float64Array( 2 ), 1, 0, new Float64Array( 1 ), 1, 0, new Int32Array( 3 ), 1, 0, new Float64Array( 3 ), 1, 0, new Float64Array( 1 ), 0 ); // eslint-disable-line max-len
		};
	}
});

tape( 'the function throws an error if provided a second argument which is less than zero', function test( t ) {
	var values;
	var i;

	values = [
		-1,
		-2,
		-3
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlagts( 1, value, new Float64Array( 3 ), 1, 0, new Float64Array( 2 ), 1, 0, new Float64Array( 2 ), 1, 0, new Float64Array( 1 ), 1, 0, new Int32Array( 3 ), 1, 0, new Float64Array( 3 ), 1, 0, new Float64Array( 1 ), 0 ); // eslint-disable-line max-len
		};
	}
});

tape( 'the function solves `(T - lambda*I)*x = y`', function test( t ) {
	var expectedTOL;
	var expectedY;
	var data;
	var info;
	var TOL;
	var IN;
	var A;
	var B;
	var C;
	var D;
	var Y;

	data = JOB1;

	A = new Float64Array( data.A );
	B = new Float64Array( data.B );
	C = new Float64Array( data.C );
	D = new Float64Array( data.D );
	IN = new Int32Array( data.IN );
	Y = new Float64Array( data.Y );
	TOL = new Float64Array( data.TOL );

	expectedY = new Float64Array( data.Y_out );
	expectedTOL = new Float64Array( data.TOL_out );

	info = dlagts( data.job, data.N, A, data.strideA, data.offsetA, B, data.strideB, data.offsetB, C, data.strideC, data.offsetC, D, data.strideD, data.offsetD, IN, data.strideIN, data.offsetIN, Y, data.strideY, data.offsetY, TOL, data.offsetTOL ); // eslint-disable-line max-len

	t.strictEqual( info, data.info, 'returns expected value' );
	t.deepEqual( Y, expectedY, 'returns expected value' );
	t.deepEqual( TOL, expectedTOL, 'returns expected value' );

	t.end();
});

